import * as T from './vendor/three.module.js';

const UP=new T.Vector3(0,1,0),smooth=t=>{const x=Math.max(0,Math.min(1,t));return x*x*(3-2*x);};
function fabricSurface(point,rows=18,columns=32){const p=[],uv=[],index=[];for(let i=0;i<=rows;i++)for(let j=0;j<=columns;j++){p.push(...point(i/rows,j/columns));uv.push(j/columns,i/rows);if(i<rows&&j<columns){const n=i*(columns+1)+j;index.push(n,n+1,n+columns+1,n+1,n+columns+2,n+columns+1);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(index);g.computeVertexNormals();return g;}

export function createPlazaSnowman(scene,{x=-6.5,y=.09,z=3}={}){
 const root=new T.Group();root.name='plaza-carrot-snowman';root.position.set(x,y,z);scene.add(root);
 const snow=new T.MeshPhysicalMaterial({color:'#f7f5ec',roughness:1,sheen:.65,sheenColor:'#dbeaf0'}),wool=new T.MeshPhysicalMaterial({color:'#e6dac3',roughness:1,sheen:.45,side:T.DoubleSide}),burgundy=new T.MeshPhysicalMaterial({color:'#76505b',roughness:.95,sheen:.45,side:T.DoubleSide}),coal=new T.MeshPhysicalMaterial({color:'#302d30',roughness:.26,clearcoat:.4}),wood=new T.MeshStandardMaterial({color:'#745842',roughness:1}),orange=new T.MeshStandardMaterial({color:'#e89f55',roughness:.86}),carrotMark=new T.MeshStandardMaterial({color:'#a76837',roughness:1}),blush=new T.MeshBasicMaterial({color:'#d8a5a1',transparent:true,opacity:.13,depthWrite:false}),white=new T.MeshBasicMaterial({color:'#fff8e6'});
 const geometries=new Set(),materials=new Set([snow,wool,burgundy,coal,wood,orange,carrotMark,blush,white]);
 const mesh=(geometry,material,parent=root)=>{geometries.add(geometry);const m=new T.Mesh(geometry,material);m.castShadow=m.receiveShadow=true;parent.add(m);return m;};
 const orb=(material,x,y,z,sx,sy,sz,parent=root)=>{const m=mesh(new T.SphereGeometry(1,32,20),material,parent);m.position.set(x,y,z);m.scale.set(sx,sy,sz);return m;};
 const tube=(points,r,material,parent=root,segments=16)=>mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),segments,r,7,false),material,parent);
 const body=orb(snow,0,.87,0,.76,.86,.67);body.name='rounded-snow-body';for(const side of [-1,1])orb(snow,side*.28,.11,.36,.25,.11,.3);for(const [yy,zz]of [[1.25,.61],[.94,.677],[.6,.645]]){orb(coal,0,yy,zz,.043,.047,.026);orb(white,-.012,yy+.014,zz+.025,.009,.011,.005);}
 const head=new T.Group();head.name='snowman-expressive-head';head.position.set(0,1.98,.015);head.scale.setScalar(1.24);root.add(head);orb(snow,0,0,0,.49,.47,.445,head);
 const eyes=[];for(const side of [-1,1]){const eye=orb(coal,side*.147,.048,.434,.047,.06,.028,head);eye.name='snowman-eye-'+side;eyes.push(eye);orb(white,-.15,.28,.83,.22,.18,.1,eye);orb(blush,side*.265,-.062,.382,.079,.039,.009,head);}
 const smilePoints=[];for(let i=0;i<=24;i++){const xx=-.14+i/24*.28,yy=-.158+.032*(xx/.14)**2;smilePoints.push([xx,yy,Math.sqrt(Math.max(0,.445**2-xx*xx-yy*yy))+.014]);}const smile=tube(smilePoints,.009,coal,head,24);smile.name='snowman-smile';const surprise=mesh(new T.TorusGeometry(.039,.008,8,24),coal,head);surprise.name='snowman-surprised-mouth';surprise.position.set(0,-.17,.42);surprise.scale.y=1.25;surprise.visible=false;
 // A soft, slouching wool hat has curved ribs, a rolled brim and a small tassel.
 const hat=fabricSurface((v,u)=>{const a=u*Math.PI*2,r=.406*Math.cos(v*Math.PI/2);return[Math.cos(a)*r+v*v*.09,.285+Math.sin(v*Math.PI/2)*.25,Math.sin(a)*r*.94-.035-v*v*.045];},18,64);mesh(hat,wool,head);
 const brim=mesh(new T.TorusGeometry(.406,.046,10,64),burgundy,head);brim.rotation.x=Math.PI/2;brim.scale.y=.94;brim.position.set(0,.285,-.035);orb(wool,.09,.566,-.08,.092,.09,.092,head);
 for(let i=0;i<18;i++){const a=i/18*Math.PI*2,points=[];for(let j=0;j<=14;j++){const v=j/14,r=.41*Math.cos(v*Math.PI/2);points.push([Math.cos(a)*r+v*v*.09,.285+Math.sin(v*Math.PI/2)*.251,Math.sin(a)*r*.94-.035-v*v*.045]);}tube(points,.0035,burgundy,head,14);}
 const wrap=fabricSurface((v,u)=>{const a=u*Math.PI*2,yy=1.68-v*.2,r=Math.max(.76*Math.sqrt(Math.max(0,1-((yy-.87)/.86)**2)),.6076*Math.sqrt(Math.max(0,1-((yy-1.98)/.5828)**2)))+.028+.006*Math.sin(a*4);return[Math.cos(a)*r,yy,Math.sin(a)*r*.9+.025];},7,64);mesh(wrap,burgundy);
 const bodyFront=(xx,yy)=>.67*Math.sqrt(Math.max(0,1-(xx/.76)**2-((yy-.87)/.86)**2))+.03;
 const scarfTails=[];for(const [xx,length]of [[-.21,.5],[-.03,.36]]){const tail=mesh(fabricSurface((v,u)=>{const px=xx+(u-.5)*.135,py=1.53-v*length;return[px,py,bodyFront(px,py)+.008*Math.sin(u*Math.PI*3)];},18,6),burgundy);scarfTails.push(tail);for(let j=0;j<6;j++){const px=xx-.053+j*.021,py=1.53-length;tube([[px,py,bodyFront(px,py)],[px,py-.05,bodyFront(px,py-.05)+.004]],.004,wool,root,4);}}
 // Carrot is an independent curved object, so the hand can actually remove it.
 const nose=new T.Group();nose.name='snowman-carrot-nose';root.add(nose);nose.scale.set(.94,.94,.76);const carrot=fabricSurface((v,u)=>{const a=u*Math.PI*2,r=.067*Math.pow(1-v,.8);return[Math.cos(a)*r+v*v*.025,Math.sin(a)*r,v*.31];},16,28);mesh(carrot,orange,nose);const base=mesh(new T.CircleGeometry(.066,28),orange,nose);base.rotation.y=Math.PI;
 for(const [zz,width]of [[.065,.045],[.135,.032],[.205,.018]])tube([[-width,.015,zz],[-width*.3,.025,zz+.003],[width*.45,.026,zz+.006]],.0025,carrotMark,nose,6);
 const noseSocket=orb(new T.MeshStandardMaterial({color:'#c6c7bd',roughness:1}),0,-.012,.445,.047,.044,.012,head);noseSocket.name='snowman-nose-socket';materials.add(noseSocket.material);
 const shoulders=[new T.Vector3(-.6,1.36,.02),new T.Vector3(.6,1.36,.02)],wrists=[new T.Vector3(-.98,1.32,.22),new T.Vector3(.98,1.32,.22)],elbows=[new T.Vector3(-.88,1.25,.06),new T.Vector3(.88,1.25,.06)],hands=[],arms=[];
 for(let side=0;side<2;side++){const hand=new T.Group();hand.name=side?'carrot-hand':'waving-hand';root.add(hand);const sign=side?1:-1;orb(wool,sign*.055,.015,.015,.105,.12,.085,hand);orb(wool,-sign*.025,-.025,.065,.048,.065,.052,hand);const cuff=mesh(new T.TorusGeometry(.067,.018,6,18),burgundy,hand);cuff.rotation.y=Math.PI/2;cuff.position.x=-sign*.03;hands.push(hand);const limb=[];for(let j=0;j<2;j++){const m=mesh(new T.CylinderGeometry(.024,.03,1,8),wood);m.name='articulated-twig-arm';limb.push(m);}arms.push(limb);}
 const home=new T.Vector3(),hold=new T.Vector3(.53,1.93,.92),nosePoint=new T.Vector3(),rightIdle=new T.Vector3(.98,1.32,.22),delta=new T.Vector3(),grab=new T.Vector3();let active=false,start=0,lastTime=0,reduced=false,disposed=false;
 function rodBetween(m,a,b){delta.copy(b).sub(a);m.position.copy(a).add(b).multiplyScalar(.5);m.scale.set(1,Math.max(.001,delta.length()),1);m.quaternion.setFromUnitVectors(UP,delta.normalize());}
 function update(time=0,still=false,player=null){if(disposed)return;const t=Number.isFinite(time)?time:0;lastTime=t;reduced=!!still;let phase=active?t-start:-1;if(still||phase>=4.2){active=false;phase=-1;}const idle=still?0:t;
  const cycle=idle%12.5,wave=!active&&!still?smooth((cycle-1.4)/.6)*(1-smooth((cycle-4.4)/.65)):0,hop=!active&&!still&&cycle>9.8&&cycle<10.6?Math.sin((cycle-9.8)/.8*Math.PI):0;
  root.position.y=y+hop*.12;root.rotation.z=still?0:Math.sin(idle*.8)*.014;root.scale.set(1+hop*.015,1-hop*.012,1+hop*.015);
  const playerYaw=player&&Number.isFinite(player.x+player.z)?Math.atan2(player.x-root.position.x,player.z-root.position.z):0;head.rotation.set(0,Math.max(-.16,Math.min(.16,playerYaw*.22))+Math.sin(idle*.43)*.025,Math.sin(idle*.65)*.018);if(active)head.rotation.z=-.045*Math.sin(Math.min(1,phase/3.3)*Math.PI);
  head.updateMatrix();home.set(0,-.012,.451).applyMatrix4(head.matrix);nosePoint.copy(home);wrists[0].set(-.98,1.32+Math.sin(idle*.8)*.045,.22);wrists[0].lerp(new T.Vector3(-.83,2.08,.24),wave);wrists[0].x+=wave*Math.sin(idle*7.2)*.08;wrists[1].copy(rightIdle);nose.rotation.set(0,0,0);nose.quaternion.copy(head.quaternion);
  if(active){const reach=smooth(phase/.65),pull=smooth((phase-.65)/.65),replace=smooth((phase-2.55)/.7),release=smooth((phase-3.25)/.95),distance=pull*(1-replace);nosePoint.lerpVectors(home,hold,distance);nosePoint.y+=distance*Math.sin(t*4.2)*.025;nose.rotation.x-=distance*.22;nose.rotation.y+=distance*.32;grab.copy(nosePoint);grab.x+=.06;grab.y-=.035;grab.z+=.09;wrists[1].lerpVectors(rightIdle,grab,reach*(1-release));head.rotation.y+=distance*.13;smile.visible=distance<.3;surprise.visible=distance>=.3;blush.opacity=.13+.12*Math.sin(Math.min(1,phase/4.2)*Math.PI);}else{smile.visible=true;surprise.visible=false;blush.opacity=.13;}
  nose.position.copy(nosePoint);const blink=idle%5.8>5.62?Math.max(.08,Math.abs((idle%5.8-5.71)/.09)):1;for(const eye of eyes)eye.scale.y=.06*(active&&phase>.7&&phase<2.5?1.14:blink);scarfTails.forEach((tail,i)=>tail.rotation.x=still?0:Math.sin(t*.8+i)*.008);
  for(let i=0;i<2;i++){const sign=i?1:-1;elbows[i].set(sign*(i&&active?.82:.88),1.25+(i&&active?.22*smooth(phase/.65)*(1-smooth((phase-3.25)/.95)):0),.07+(i&&active?.14:0));rodBetween(arms[i][0],shoulders[i],elbows[i]);rodBetween(arms[i][1],elbows[i],wrists[i]);hands[i].position.copy(wrists[i]);hands[i].rotation.set(0,i&&active?-.55:0,i&&active?-.35:i===0?wave*(.5+Math.sin(idle*7.2)*.24):Math.sin(idle*.8)*.04);}
 }
 function interact(time=lastTime){if(disposed||active)return false;start=Number.isFinite(time)?time:lastTime;active=!reduced;update(start,reduced);return true;}
 function dispose(){if(disposed)return;disposed=true;root.removeFromParent();for(const geometry of geometries)geometry.dispose();for(const material of materials)material.dispose();}
 function mergeStatic(parent,exclude=[]){const batches=new Map();for(const child of parent.children){if(!child.isMesh||child.children.length||exclude.includes(child))continue;if(!batches.has(child.material))batches.set(child.material,[]);batches.get(child.material).push(child);}for(const [material,items]of batches){if(items.length<2)continue;const arrays={position:[],normal:[],uv:[]};for(const child of items){child.updateMatrix();let g=child.geometry.clone().applyMatrix4(child.matrix);if(g.index){const old=g;g=g.toNonIndexed();old.dispose();}for(const key of Object.keys(arrays))arrays[key].push(...g.attributes[key].array);g.dispose();child.removeFromParent();}const geometry=new T.BufferGeometry();for(const [key,values]of Object.entries(arrays))geometry.setAttribute(key,new T.Float32BufferAttribute(values,key==='uv'?2:3));mesh(geometry,material,parent).name='snowman-merged-finish';}}
 mergeStatic(root,[...arms.flat(),...scarfTails]);mergeStatic(head,[...eyes,smile,surprise,noseSocket]);mergeStatic(nose);for(const hand of hands)mergeStatic(hand);
 update(0,false);return{root,update,interact,dispose,collision:{x,z,r:1.02},get busy(){return active;}};
}
